-- NFL coaches by role and season: ability means
select season, coach__job__role role, count(*) n, round(avg(coach__age),1) age, round(avg(coach__ability__scheme),2) scheme, round(avg(coach__ability__game_management),2) gm, round(avg(coach__ability__teaching__0),2) t_qb, round(avg(coach__ability__teaching__1),2) t_rb, round(avg(coach__ability__teaching__2),2) t_rec, round(avg(coach__ability__teaching__3),2) t_ol, round(avg(coach__ability__teaching__4),2) t_dl, round(avg(coach__ability__teaching__5),2) t_lb, round(avg(coach__ability__teaching__6),2) t_db, round(avg(coach__learning_ceiling),2) ceil, round(avg(coach__reputation),2) rep from log_coaches where coach__job__employer__Nfl is not null and season between 2025 and 2035 group by season, role order by role, season
-- draftees: first NFL season overall by unit and draft year
select year, unit, count(*) n, round(avg(overall),2) mean_overall from (select s.year, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, h.overall from people__pro__seasons s join people p on p._row = s._parent join people__player__history h on h._parent = s._parent and h.age = s.year - p.class_of + 18 where json_extract(p.pro__draft,'$[0]') = s.year and h.level = 'NFL' union all select s.year, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' when a.player__position in ('CB','S') then 'DB' else a.player__position end, h.overall from alumni__pro__seasons s join alumni a on a._row = s._parent join alumni__player__history h on h._parent = s._parent and h.age = s.year - a.class_of + 18 where json_extract(a.pro__draft,'$[0]') = s.year and h.level = 'NFL') where year between 2024 and 2035 and unit in ('OL','DL','RB','QB','WR','LB','DB','TE') group by year, unit order by unit, year
-- starters mean age by unit and year
select year, unit, count(*) n, round(avg(age),2) mean_age from (select s.year, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, h.age from people__pro__seasons s join people p on p._row = s._parent join people__player__history h on h._parent = s._parent and h.age = s.year - p.class_of + 18 where s.starts >= 8 and h.level = 'NFL' union all select s.year, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' when a.player__position in ('CB','S') then 'DB' else a.player__position end, h.age from alumni__pro__seasons s join alumni a on a._row = s._parent join alumni__player__history h on h._parent = s._parent and h.age = s.year - a.class_of + 18 where s.starts >= 8 and h.level = 'NFL') where year between 2024 and 2035 and unit in ('OL','DL','RB','QB','WR','LB','DB','TE') group by year, unit order by unit, year
-- starters body: mean weight and height by unit and year (current body)
select year, unit, count(*) n, round(avg(w),1) weight, round(avg(ht),2) height from (select s.year, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, p.player__body__weight w, p.player__body__height ht from people__pro__seasons s join people p on p._row = s._parent where s.starts >= 8 union all select s.year, case when a.player__position in ('OT','IOL') then 'OL' when a.player__position in ('DT','EDGE') then 'DL' when a.player__position in ('CB','S') then 'DB' else a.player__position end, a.player__body__weight, a.player__body__height from alumni__pro__seasons s join alumni a on a._row = s._parent where s.starts >= 8) where year between 2024 and 2035 and unit in ('OL','DL','RB','QB','WR','LB','DB','TE') group by year, unit order by unit, year
-- yearly change in overall for NFL starters by unit, 2025-28 vs 2032-35 (next season minus this)
select period, unit, count(*) n, round(avg(d),3) mean_change from (select case when s.year between 2025 and 2028 then 'early' else 'late' end period, case when p.player__position in ('OT','IOL') then 'OL' when p.player__position in ('DT','EDGE') then 'DL' when p.player__position in ('CB','S') then 'DB' else p.player__position end unit, h2.overall - h.overall d from people__pro__seasons s join people p on p._row = s._parent join people__player__history h on h._parent = s._parent and h.age = s.year - p.class_of + 18 join people__player__history h2 on h2._parent = h._parent and h2.age = h.age + 1 where s.starts >= 8 and h.level = 'NFL' and h2.level = 'NFL' and (s.year between 2025 and 2028 or s.year between 2032 and 2034)) where unit in ('OL','DL','RB','QB','WR','LB','DB','TE') group by period, unit order by unit, period
